import itertools
D=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)"'!=(0,0)]
variants=[]
for center in [0,1]:
 for side in [None,0,1,2,3]:
  if side is not None:
   sp={(r,c) for r in range(3) for c in range(3)}
   if not center: sp.discard((1,1))
   sidecoord=[(0,1),(1,2),(2,1),(1,0)][side]; sp.discard(sidecoord)
   rbadcbad=[(1,0),(0,-1),(-1,0),(0,1)][side]
   variants.append((sp,rbadcbad,f'"'c{center}s{side}'))
  else:
   for d1,d2 in itertools.product([0,1],repeat=2):
    sp={(r,c) for r in range(3) for c in range(3)}
    if not center: sp.discard((1,1))
    if d1: sp-={(0,0),(2,2)}
    if d2: sp-={(0,2),(2,0)}
    variants.append((sp,None,f'c{center}d{d1}{d2}'))
for d in D:
 sets=[]
 for sp,bad,name in variants:
  if bad==d: continue
  dr,dc=d
  partial={p for p in sp if p[0]*dr+1-dr+p[1]*dc+1-dc<2}
  assert partial
  sets.append(partial)
 coords=list(itertools.product(range(3),repeat=2)); best=None
 for k in range(1,10):
  for comb in itertools.combinations(coords,k):
   if all(set(comb)&s for s in sets): best=comb;break
  if best:break
 print(d,'min',len(best),best,'partial union',sorted(set.union(*sets)))
PY"

